class sample
{
    int i;
    double k;
    public sample(int ii, double kk)
    {
        i = ii;
        k = kk;
        Console.Write((i + k) + " ");
    }
    ~sample()
    {
        Console.Write((i - k) + " ");
    }
}
class Program
{
    static void Main(string[] args)
    {
        sample s = new sample(8, 2.5);
    }
